edits.before:
onClick (event) {
  if (event.target.closest(`[${ this.config.closeTrigger }]`)) {
    event.preventDefault()
    event.stopPropagation()
    this.closeModal(event)
  }
}

edits.after:
onClick (event) {
  const closeTrigger = `[${ this.config.closeTrigger }]`
  const target = event.target.closest(closeTrigger)
  if (!target) return

  const overlay = this.modal.querySelector('.modal__overlay')
  if (target === overlay && event.target !== overlay) {
    // Click originated inside the modal, not on the overlay itself
    return
  }

  event.preventDefault()
  event.stopPropagation()
  this.closeModal(event)
}
